#[derive(Clone, Debug, PartialEq)]
pub struct ClusterPutWeightedRoutingRequestWire {
    pub parent_task_node: String,
    pub parent_task_id: Option<i64>,
    pub cluster_manager_timeout: TimeValueWire,
    pub attribute_name: String,
    pub weights: BTreeMap<String, f64>,
    pub version: i64,
}

impl Default for ClusterPutWeightedRoutingRequestWire {
    fn default() -> Self {
        Self {
            parent_task_node: String::new(),
            parent_task_id: None,
            cluster_manager_timeout: TimeValueWire::seconds(30),
            attribute_name: String::new(),
            weights: BTreeMap::new(),
            version: -2,
        }
    }
}

impl ClusterPutWeightedRoutingRequestWire {
    pub fn write(&self, output: &mut StreamOutput) {
        write_parent_task_id(output, &self.parent_task_node, self.parent_task_id);
        self.cluster_manager_timeout.write(output);
        output.write_string(&self.attribute_name);
        write_generic_string_double_map(output, &self.weights);
        output.write_i64(self.version);
    }

    pub fn read(bytes: Bytes) -> Result<Self, TransportActionWireError> {
        let mut input = StreamInput::new(bytes);
        let (parent_task_node, parent_task_id) = read_parent_task_id(&mut input)?;
        let request = Self {
            parent_task_node,
            parent_task_id,
            cluster_manager_timeout: TimeValueWire::read(&mut input)?,
            attribute_name: input.read_string()?,
            weights: read_generic_string_double_map(&mut input)?,
            version: input.read_i64()?,
        };
        require_no_trailing_bytes(&input)?;
        Ok(request)
    }

    pub fn reject_unsupported_execution(&self) -> Result<(), TransportActionWireError> {
        if self.cluster_manager_timeout != TimeValueWire::seconds(30) {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "put weighted routing cluster-manager timeout",
                reason: "custom cluster-manager timeout requires weighted routing metadata mutation coordination",
            });
        }
        if self.attribute_name.is_empty() {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "put weighted routing missing attribute",
                reason:
                    "OpenSearch put-weighted-routing requests require an awareness attribute name",
            });
        }
        if self.weights.is_empty() {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "put weighted routing missing weights",
                reason: "OpenSearch put-weighted-routing requests require at least one weight",
            });
        }
        if self.version == -2 {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "put weighted routing missing version",
                reason:
                    "OpenSearch put-weighted-routing requests require a weighted routing version",
            });
        }
        if self.weights.values().any(|weight| !weight.is_finite()) {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "put weighted routing non-finite weight",
                reason: "weighted routing metadata requires finite numeric weights before mutation can be admitted",
            });
        }
        let zero_weight_count = self
            .weights
            .values()
            .filter(|weight| **weight == 0.0)
            .count();
        if zero_weight_count > self.weights.len() / 2 {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "put weighted routing too many zero weights",
                reason: "OpenSearch put-weighted-routing validation rejects more than half of values with zero weight",
            });
        }
        Err(TransportActionWireError::UnsupportedWireShape {
            shape: "put weighted routing execution",
            reason: "put-weighted-routing transport execution requires weighted routing metadata mutation and acknowledgement rendering",
        })
    }
}

