fn write_generic_map_presence(output: &mut StreamOutput, has_entries: bool) {
    if has_entries {
        output.write_byte(10);
        output.write_vint(1);
        output.write_string("metadata");
        output.write_byte(0);
        output.write_string("present");
    } else {
        output.write_byte(255);
    }
}

fn read_generic_map_has_entries(input: &mut StreamInput) -> Result<bool, TransportActionWireError> {
    match input.read_byte()? {
        255 => Ok(false),
        9 | 10 => {
            let len = input.read_vint()?;
            if len < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic map length",
                    reason: "OpenSearch generic map length must be non-negative",
                });
            }
            for _ in 0..len {
                let _key = input.read_string()?;
                skip_generic_value(input)?;
            }
            Ok(len > 0)
        }
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic map type",
            reason:
                "OpenSearch create-snapshot user metadata must be encoded as a generic map or null",
        }),
    }
}

fn write_settings_string_map(output: &mut StreamOutput, values: &BTreeMap<String, String>) {
    output.write_vint(values.len() as i32);
    for (key, value) in values {
        output.write_string(key);
        output.write_byte(0);
        output.write_string(value);
    }
}

fn read_settings_string_map(
    input: &mut StreamInput,
) -> Result<BTreeMap<String, String>, TransportActionWireError> {
    let len = input.read_vint()?;
    if len < 0 {
        return Err(TransportActionWireError::UnsupportedWireShape {
            shape: "settings map length",
            reason: "OpenSearch settings map length must be non-negative",
        });
    }
    let mut values = BTreeMap::new();
    for _ in 0..len {
        let key = input.read_string()?;
        match input.read_byte()? {
            0 => {
                values.insert(key, input.read_string()?);
            }
            255 => {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "settings map null value",
                    reason: "null setting values require OpenSearch Settings null-value semantics",
                });
            }
            _ => {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "settings map generic value",
                    reason: "non-string setting values require OpenSearch Settings generic-value semantics",
                });
            }
        }
    }
    Ok(values)
}

fn write_generic_string_double_map(output: &mut StreamOutput, values: &BTreeMap<String, f64>) {
    output.write_byte(10);
    output.write_vint(values.len() as i32);
    for (key, value) in values {
        output.write_string(key);
        output.write_byte(4);
        output.write_f64(*value);
    }
}

fn read_generic_string_double_map(
    input: &mut StreamInput,
) -> Result<BTreeMap<String, f64>, TransportActionWireError> {
    match input.read_byte()? {
        9 | 10 => {
            let len = read_len(input)?;
            let mut values = BTreeMap::new();
            for _ in 0..len {
                let key = input.read_string()?;
                let generic_type = input.read_byte()?;
                if generic_type != 4 {
                    return Err(TransportActionWireError::UnsupportedWireShape {
                        shape: "generic double map value",
                        reason: "weighted routing wire payload only supports string keys with double weight values",
                    });
                }
                values.insert(key, input.read_f64()?);
            }
            Ok(values)
        }
        255 => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic double map null",
            reason: "OpenSearch put-weighted-routing requests require a non-null weights map",
        }),
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic double map type",
            reason: "weighted routing wire payload must be encoded as an OpenSearch generic map",
        }),
    }
}

fn skip_generic_value(input: &mut StreamInput) -> Result<(), TransportActionWireError> {
    match input.read_byte()? {
        255 => Ok(()),
        0 => {
            let _ = input.read_string()?;
            Ok(())
        }
        1 | 3 => {
            let _ = input.read_i32()?;
            Ok(())
        }
        2 | 4 | 12 => {
            let _ = input.read_i64()?;
            Ok(())
        }
        5 => {
            let _ = input.read_bool()?;
            Ok(())
        }
        6 => {
            let len = input.read_vint()?;
            if len < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic byte array length",
                    reason: "OpenSearch generic byte array length must be non-negative",
                });
            }
            let _ = input.read_bytes(len as usize)?;
            Ok(())
        }
        7 | 8 | 24 | 25 => {
            let len = input.read_vint()?;
            if len < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic collection length",
                    reason: "OpenSearch generic collection length must be non-negative",
                });
            }
            for _ in 0..len {
                skip_generic_value(input)?;
            }
            Ok(())
        }
        9 | 10 => {
            let len = input.read_vint()?;
            if len < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic nested map length",
                    reason: "OpenSearch generic map length must be non-negative",
                });
            }
            for _ in 0..len {
                let _key = input.read_string()?;
                skip_generic_value(input)?;
            }
            Ok(())
        }
        11 => {
            let _ = input.read_byte()?;
            Ok(())
        }
        16 => {
            let _ = input.read_bytes(2)?;
            Ok(())
        }
        17 | 19 => {
            let len = input.read_vint()?;
            if len < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic int array length",
                    reason: "OpenSearch generic int array length must be non-negative",
                });
            }
            for _ in 0..len {
                let _ = input.read_i32()?;
            }
            Ok(())
        }
        18 | 20 => {
            let len = input.read_vint()?;
            if len < 0 {
                return Err(TransportActionWireError::UnsupportedWireShape {
                    shape: "generic long array length",
                    reason: "OpenSearch generic long array length must be non-negative",
                });
            }
            for _ in 0..len {
                let _ = input.read_i64()?;
            }
            Ok(())
        }
        13 | 23 => {
            let _time_zone_id = input.read_string()?;
            let _millis = input.read_i64()?;
            Ok(())
        }
        14 => {
            let _ = input.read_bytes_reference()?;
            Ok(())
        }
        15 => {
            let _ = input.read_string()?;
            Ok(())
        }
        _ => Err(TransportActionWireError::UnsupportedWireShape {
            shape: "generic value type",
            reason: "OpenSearch generic value type is not supported by the create-snapshot metadata boundary",
        }),
    }
}

