        let response = SteelsearchShardSearchResponseWire { result };
        let mut output = StreamOutput::new();
        response.write(&mut output).unwrap();
        assert_eq!(
            SteelsearchShardSearchResponseWire::read(output.freeze()).unwrap(),
            response
        );
